import sys

def input_analysis(s):
    length = len(s)
    in_parentheses = False
    total_words = 0
    max_word = 0
    current_length = 0
    for i in range(length):
        c = s[i]
        if c == '(':
            if current_length > 0:
                if current_length > max_word:
                    max_word = current_length
                current_length = 0
            in_parentheses = True
        elif c == ')':
            if current_length > 0:
                total_words += 1
                current_length = 0
            in_parentheses = False
        elif c == '_':
            if current_length > 0:
                if in_parentheses:
                    total_words += 1
                else:
                    if current_length > max_word:
                        max_word = current_length
                current_length = 0
        else:
            current_length += 1
    if current_length > 0:
        if in_parentheses:
            total_words += 1
        else:
            if current_length > max_word:
                max_word = current_length
    return str(max_word) + " " + str(total_words)

def main():
    lines = sys.stdin.read().splitlines()
    i = 0
    while i < len(lines):
        # Skip empty lines if any
        if lines[i].strip() == '':
            i += 1
            continue
        # Read and ignore the first line as per original code
        # and process the next line
        if i + 1 < len(lines):
            print(input_analysis(lines[i + 1]))
            i += 2
        else:
            break

if __name__ == "__main__":
    main()

